css:
.print-format-doc { line-height: 1.3; }
.print-format-doc .section--grid .field .value { min-height: 1.35em; }
.print-format-doc .section--grid .child-table .table { font-size: 1em; }
[data-fieldname][data-fieldtype] .label.label { font-size: 0.84em; font-weight: 400; color: #6b7280; margin-bottom: 1px; }
[data-fieldname="net_total"][data-fieldtype] .label.label, [data-fieldname="total"][data-fieldtype] .label.label, [data-fieldname="total_qty"][data-fieldtype] .label.label, [data-fieldname="total_net_weight"][data-fieldtype] .label.label, [data-fieldname="rounding_adjustment"][data-fieldtype] .label.label, [data-fieldname="total_advance"][data-fieldtype] .label.label, [data-fieldname="outstanding_amount"][data-fieldtype] .label.label { font-size: 1em; }
[data-fieldname="rounded_total"][data-fieldtype] .label.label, [data-fieldname="grand_total"][data-fieldtype] .label.label { font-size: 1em; font-weight: 700; color: #1f2328; }
[data-fieldname$="address_display"][data-fieldtype] .value, [data-fieldname="shipping_address"][data-fieldtype] .value { font-size: 0.94em; line-height: 1.3; }
td[data-fieldtype="Currency"], td[data-fieldtype="Float"], td[data-fieldtype="Percent"], td[data-fieldtype="Date"] { white-space: nowrap; }
img.qrcode { display: block; width: 100%; height: auto; }
td[data-fieldtype="Percent"], th[data-fieldtype="Percent"], td[data-fieldname="discount_percentage"], th[data-fieldname="discount_percentage"] { text-align: right; }
[data-fieldname="payment_schedule"][data-fieldtype] td { font-weight: 500; color: #1f2328; }
.print-format-doc [document-status] { margin-bottom: 2px; }
.print-format-doc [document-status] h4 { font-size: 12px; font-weight: 600; letter-spacing: 0.12em; color: #b91c1c; }

